{
  "name": "GRBL数控运动控制设备",
  "name_en": "GRBL-based CNC motion control device",
  "manufacturer": "",
  "description": "基于 GRBL 固件的数控运动控制设备，通过串口接收 G-code 指令来驱动多轴运动。常见于小型 CNC 雕刻机、运动平台或激光加工设备，在实验室中可用于样品定位、自动扫描、轨迹运动和简单加工控制。",
  "description_en": "A CNC motion control device running GRBL firmware, receiving G-code commands over a serial connection to drive multi-axis motion. It is commonly used in small CNC engravers, positioning stages, or laser processing systems, and in laboratories for sample positioning, automated scanning, trajectory motion, and simple machining control.",
  "tag_hints": [
    "GRBL",
    "G-code control",
    "CNC motion control",
    "multi-axis positioning",
    "serial communication",
    "motorized stage",
    "laser engraver"
  ],
  "actions": [
    {
      "action_name": "auto-startPooling",
      "description": "启动与设备的串口轮询通信。",
      "description_en": "Start serial polling communication with the device."
    },
    {
      "action_name": "auto-stopPooling",
      "description": "停止与设备的串口轮询通信。",
      "description_en": "Stop serial polling communication with the device."
    },
    {
      "action_name": "auto-abort",
      "description": "中止当前通信过程。",
      "description_en": "Abort the current communication process."
    },
    {
      "action_name": "auto-clearCom",
      "description": "清空待发送和待处理的通信队列。",
      "description_en": "Clear the pending communication queues."
    },
    {
      "action_name": "auto-realTimePush",
      "description": "以实时方式将一条 G-code 指令加入发送队列。",
      "description_en": "Push a G-code command to the transmission queue in real-time mode."
    },
    {
      "action_name": "auto-gcodePush",
      "description": "按先进先出顺序将 G-code 指令加入常规执行队列。",
      "description_en": "Push a G-code command into the normal execution queue in FIFO order."
    },
    {
      "action_name": "auto-resetSerial",
      "description": "重置与设备的串口连接。",
      "description_en": "Reset the serial connection to the device."
    },
    {
      "action_name": "auto-gcodeInsert",
      "description": "将一条 G-code 指令以前插方式加入队列，使其优先执行。",
      "description_en": "Insert a G-code command at the front of the queue for priority execution."
    },
    {
      "action_name": "auto-run",
      "description": "启动设备串口通信处理循环。",
      "description_en": "Start the device serial communication processing loop."
    }
  ]
}

